/**
 * One branch or tag a push changes.
 */
public struct GitRefView: Equatable, Hashable {
    /**
     * Full name: `refs/heads/main`, `refs/tags/v1.0`.
     */
    public var name: String
    /**
     * "branch" | "tag" | "other"
     */
    public var kind: String
    /**
     * `main`, `v1.0` (the full name for other refs).
     */
    public var shortName: String
    /**
     * "create" | "update" | "delete"
     */
    public var change: String
    /**
     * An update that does not only add commits: it rewrites history, or that could not be checked.
     */
    public var force: Bool
    /**
     * The desktop app could not tell whether the update only adds commits (treated as a force push).
     */
    public var forceUnknown: Bool
    /**
     * Commits the ref gains; may be more than `commits` lists.
     */
    public var commitCount: UInt32
    /**
     * Newest first.
     */
    public var commits: [GitCommitView]
    /**
     * Files that differ; may be more than `files` lists.
     */
    public var filesChanged: UInt32
    public var files: [GitFileView]
    /**
     * Lines added and removed in all files; `None` when not every file could be counted.
     */
    public var additions: UInt64?
    public var deletions: UInt64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Full name: `refs/heads/main`, `refs/tags/v1.0`.
         */name: String, 
        /**
         * "branch" | "tag" | "other"
         */kind: String, 
        /**
         * `main`, `v1.0` (the full name for other refs).
         */shortName: String, 
        /**
         * "create" | "update" | "delete"
         */change: String, 
        /**
         * An update that does not only add commits: it rewrites history, or that could not be checked.
         */force: Bool, 
        /**
         * The desktop app could not tell whether the update only adds commits (treated as a force push).
         */forceUnknown: Bool, 
        /**
         * Commits the ref gains; may be more than `commits` lists.
         */commitCount: UInt32, 
        /**
         * Newest first.
         */commits: [GitCommitView], 
        /**
         * Files that differ; may be more than `files` lists.
         */filesChanged: UInt32, files: [GitFileView], 
        /**
         * Lines added and removed in all files; `None` when not every file could be counted.
         */additions: UInt64?, deletions: UInt64?) {
        self.name = name
        self.kind = kind
        self.shortName = shortName
        self.change = change
        self.force = force
        self.forceUnknown = forceUnknown
        self.commitCount = commitCount
        self.commits = commits
        self.filesChanged = filesChanged
        self.files = files
        self.additions = additions
        self.deletions = deletions
    }

    

    
}

