/**
 * Read grants: any combination of the read fields (at least one). Send grants: recipients.
 */
public struct GrantScopeChoice: Equatable, Hashable {
    /**
     * read: every message, any search or read, for a limited time (needs `duration_secs`, at most 30 days);
     * cannot be combined with the other read fields
     */
    public var allMail: Bool
    /**
     * read: `message_ids` = the selected ids
     */
    public var selectedMessagesOnly: Bool
    /**
     * read: `from` Exact
     */
    public var senderAddresses: [String]
    /**
     * read: `from` Domain
     */
    public var senderDomains: [String]
    /**
     * read/send: subject contains this literal text (`Pattern::literal`)
     */
    public var subjectPattern: String?
    /**
     * send: recipients Exact
     */
    public var recipientAddresses: [String]
    /**
     * send: recipients Domain
     */
    public var recipientDomains: [String]
    /**
     * Another integration: the ids of the things (chats, calendars, ...) the permission covers. With `all_mail` it
     * covers every one of them, for a limited time.
     */
    public var resources: [String]
    /**
     * Another integration, a permission to change things: the kinds of change it allows (see `ApprovalView.classes`).
     * Empty = the kind of the request itself.
     */
    public var classes: [String]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * read: every message, any search or read, for a limited time (needs `duration_secs`, at most 30 days);
         * cannot be combined with the other read fields
         */allMail: Bool, 
        /**
         * read: `message_ids` = the selected ids
         */selectedMessagesOnly: Bool, 
        /**
         * read: `from` Exact
         */senderAddresses: [String], 
        /**
         * read: `from` Domain
         */senderDomains: [String], 
        /**
         * read/send: subject contains this literal text (`Pattern::literal`)
         */subjectPattern: String?, 
        /**
         * send: recipients Exact
         */recipientAddresses: [String], 
        /**
         * send: recipients Domain
         */recipientDomains: [String], 
        /**
         * Another integration: the ids of the things (chats, calendars, ...) the permission covers. With `all_mail` it
         * covers every one of them, for a limited time.
         */resources: [String], 
        /**
         * Another integration, a permission to change things: the kinds of change it allows (see `ApprovalView.classes`).
         * Empty = the kind of the request itself.
         */classes: [String]) {
        self.allMail = allMail
        self.selectedMessagesOnly = selectedMessagesOnly
        self.senderAddresses = senderAddresses
        self.senderDomains = senderDomains
        self.subjectPattern = subjectPattern
        self.recipientAddresses = recipientAddresses
        self.recipientDomains = recipientDomains
        self.resources = resources
        self.classes = classes
    }

    

    
}

