/**
 * Autopilot's view of one request, for the approval screen (spec §10).
 */
public struct SuggestionView: Equatable, Hashable {
    public var requestId: String
    /**
     * What Autopilot would do in Auto mode, gates aside (`Ask` when it cannot judge).
     */
    public var verdict: Verdict
    /**
     * The mode the request was evaluated in.
     */
    public var mode: AutopilotMode
    public var pApprove: Float
    public var pDeny: Float
    /**
     * 1 − normalised entropy of (approve, deny, ask).
     */
    public var confidence: Float
    /**
     * One line, e.g. "Like 4 times you approved: Push to a branch · dkat/reins".
     */
    public var reason: String
    public var neighbours: [NeighbourView]
    public var profileId: String
    public var profileName: String
    public var classKey: String
    /**
     * The target was never approved for this connection before.
     */
    public var novel: Bool
    /**
     * Always waits for the user (hard floor, spec §2).
     */
    public var floor: Bool
    /**
     * The model ran (false: no model, Manual mode, floor, or a failure — see `reason`).
     */
    public var judged: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(requestId: String, 
        /**
         * What Autopilot would do in Auto mode, gates aside (`Ask` when it cannot judge).
         */verdict: Verdict, 
        /**
         * The mode the request was evaluated in.
         */mode: AutopilotMode, pApprove: Float, pDeny: Float, 
        /**
         * 1 − normalised entropy of (approve, deny, ask).
         */confidence: Float, 
        /**
         * One line, e.g. "Like 4 times you approved: Push to a branch · dkat/reins".
         */reason: String, neighbours: [NeighbourView], profileId: String, profileName: String, classKey: String, 
        /**
         * The target was never approved for this connection before.
         */novel: Bool, 
        /**
         * Always waits for the user (hard floor, spec §2).
         */floor: Bool, 
        /**
         * The model ran (false: no model, Manual mode, floor, or a failure — see `reason`).
         */judged: Bool) {
        self.requestId = requestId
        self.verdict = verdict
        self.mode = mode
        self.pApprove = pApprove
        self.pDeny = pDeny
        self.confidence = confidence
        self.reason = reason
        self.neighbours = neighbours
        self.profileId = profileId
        self.profileName = profileName
        self.classKey = classKey
        self.novel = novel
        self.floor = floor
        self.judged = judged
    }

    

    
}

