/**
 * Every failure the core reports to Kotlin (contracts §D). Messages never
 * contain secrets or URLs.
 */
public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NotLoggedIn
    case TwoFactorRequired
    case UnsupportedTwoFactor
    case InvalidCredentials
    case Network(reason: String
    )
    case Server(status: UInt16, reason: String
    )
    case GmailNeedsConsent
    case Gmail(reason: String
    )
    /**
     * An integration besides Gmail failed; the reason is safe to show.
     */
    case Service(reason: String
    )
    /**
     * An integration needs the user to sign in or allow something again (a Telegram session that ended).
     */
    case ServiceNeedsAttention(reason: String
    )
    case NotFound
    case Invalid(reason: String
    )
    case Storage(reason: String
    )
    /**
     * `register_device`: another phone approves for this account, and this one may not take over yet. The app offers
     * the two ways: the other phone's approval ("add another phone", `join_begin`) or the recovery code (or the
     * master password) with `unlock_account`; then `register_device` again.
     */
    case OtherApprovalDevice

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotLoggedIn
        case 2: return .TwoFactorRequired
        case 3: return .UnsupportedTwoFactor
        case 4: return .InvalidCredentials
        case 5: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Server(
            status: try FfiConverterUInt16.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .GmailNeedsConsent
        case 8: return .Gmail(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Service(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 10: return .ServiceNeedsAttention(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 11: return .NotFound
        case 12: return .Invalid(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 13: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 14: return .OtherApprovalDevice

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NotLoggedIn:
            writeInt(&buf, Int32(1))
        
        
        case .TwoFactorRequired:
            writeInt(&buf, Int32(2))
        
        
        case .UnsupportedTwoFactor:
            writeInt(&buf, Int32(3))
        
        
        case .InvalidCredentials:
            writeInt(&buf, Int32(4))
        
        
        case let .Network(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Server(status,reason):
            writeInt(&buf, Int32(6))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case .GmailNeedsConsent:
            writeInt(&buf, Int32(7))
        
        
        case let .Gmail(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Service(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ServiceNeedsAttention(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .NotFound:
            writeInt(&buf, Int32(11))
        
        
        case let .Invalid(reason):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .OtherApprovalDevice:
            writeInt(&buf, Int32(14))
        
        }
    }
}


